H.background();
const a1 = P.a1, d = P.d, r = P.r, mode = P.mode;
const geometric = mode >= 0.5;
const N = 10;
const term = (n) => geometric ? a1 * Math.pow(r, n - 1) : a1 + (n - 1) * d;
// Fit y-range to the ACTUAL terms so drawn dots equal the printed values
// (no clamp mismatch between the readout and the plotted point).
let lo = Infinity, hi = -Infinity;
for (let n = 1; n <= N; n++) {
  const y = term(n);
  if (Number.isFinite(y)) { if (y < lo) lo = y; if (y > hi) hi = y; }
}
if (!Number.isFinite(lo)) { lo = 0; hi = 1; }
if (hi - lo < 1) { hi = lo + 1; }
const padY = (hi - lo) * 0.12 + 0.5;
const v = H.plot2d({ xMin: 0, xMax: 11, yMin: lo - padY, yMax: hi + padY });
v.grid(); v.axes();
const pts = [];
for (let n = 1; n <= N; n++) {
  let y = term(n);
  if (!Number.isFinite(y)) y = 0;
  pts.push([n, y]);
}
v.path(pts, { color: H.colors.accent, width: 2, dash: [5, 5] });
for (let n = 1; n <= N; n++) {
  v.dot(pts[n - 1][0], pts[n - 1][1], { r: 5, fill: H.colors.accent });
}
const k = 1 + Math.floor((t * 1.2) % N);
v.dot(pts[k - 1][0], pts[k - 1][1], { r: 8 + 2 * Math.sin(t * 4), fill: H.colors.warn });
const curVal = pts[k - 1][1];
v.line(k, lo - padY, k, pts[k - 1][1], { color: H.colors.violet, width: 1.5, dash: [3, 3] });
H.text(geometric ? "Geometric:  a_n = a1 · r^(n−1)" : "Arithmetic:  a_n = a1 + (n−1)·d", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text((geometric ? "a1 = " + a1.toFixed(1) + "   ratio r = " + r.toFixed(2) : "a1 = " + a1.toFixed(1) + "   difference d = " + d.toFixed(2)) + "    a_" + k + " = " + curVal.toFixed(2), 24, 52, { color: H.colors.sub, size: 13 });
H.text(geometric ? "each term MULTIPLIES by r" : "each term ADDS d", 24, H.H - 16, { color: H.colors.good, size: 13 });
H.legend([{ label: "term a_n", color: H.colors.accent }, { label: "current term", color: H.colors.warn }], H.W - 170, 28);
